def solve(y, x):
    ans = math.inf
    for i in range(1, len(x)):
        curr = i * 2 - 1 if x[i] > x[i-1] else math.inf
        last = x[i]
        cnt = 0
        while True:
            first = max(last + 1-cnt, 0)
            second = min(first + max(last - first, 0)*2 + 1, ans)
            if first >= second:
                break
            else:
                cnt += 1
            last = second
        ans = min(ans, curr + cnt * (x[i] - x[0]))
