def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

# Function to find divisors of a given number
def find_divisors(n, i=2, factors=None):
    if factors is None: factors = set()
    while i * i <= n:
        if not n % (i * i):
            factors.add(i)
            n //= i * i
        else: i += 1
    return factors

