    diff_pairs = []
    for i in range(len(sorted_diffs)):
        for j in range(i + 1 if len(sorted_diffs) == i + 1 else (i + 2), len(sorted_diffs)):
            diff_pairs.append((sorted_diffs[i], sorted_diffs[j]))

    best_score = n - min_draws
    target_index = bisect_right(sorted(diffs), int(sqrt(best_score)))

    result_a = []
    result_b = []

    cur_i = 0
    for pair in diff_pairs:
        while best_score >= (pair[0] + pair[1]):
