import sys

def solve():
    t = int(input())
    for _ in range(t):
        a, b = input().split()

        # Determine size based on last character (S, M, L)
        sizes = {'M': 2, 'L': 3, 'S': 1}

        if not all(c in ['X', 'S', 'L'] + list(sizes.keys()) for c in a):
            raise ValueError("Invalid size string: {}".format(a))
        if not all(c in ['X', 'S', 'L'] + list(sizes.keys()) for c in b):
            raise ValueError("Invalid size string: {}".format(b))

        # Check if one size is larger than the other
        larger_size = max(a[-1], b[-1])
        smaller_size = min(a[-1], b[-1])

        if a != b and sizes[larger_size] > sizes[smaller_size]:
            print('>')
        elif a == b:
            # Check for extra 'X's, which decrease the size
            extra_x_a = len([c for c in a if c == 'X'])
            extra_x_b = len([c for c in b if c == 'X'])

            if extra_x_a < extra_x_b:
                print('<')
            elif extra_x_a > extra_x_b:
                print('>')
            else:
                # If number of 'X's is equal, they are equivalent sizes
                print('=')
        else:
            # If equal size symbols but different numbers of 'X's,
            # the one with more 'X's is smaller
            if len([c for c in a if c == 'X']) > len([c for c in b if c == 'X']):
                print('<')
            elif len([c for c in a if c == 'X']) < len([c for c in b if c == 'X']):
